// Manually implemented — not generated by codegen.
// PACKET_CZ_REQUEST_CHAT has no C struct definition in rAthena; it is a
// variable-length packet parsed manually in clif.cpp.
//
// EncodePublicChat encodes the C→S variant (0x008C) used when a client
// sends a global chat message. packetver >= 20040726 uses 0x00F3 instead.
//
// Wire format: uint16 packetType | uint16 packetLength | "Name : Message\0"

package encode

import (
	"encoding/binary"

	"github.com/lenaxia/rathena-client/pkg/send"
)

// EncodePublicChat encodes a PublicChat packet (CZ_REQUEST_CHAT).
// Returns a variable-length byte slice.
func EncodePublicChat(req send.PublicChat, packetver uint32) []byte {
	var pktID uint16
	if packetver >= 20040726 {
		pktID = 0x00F3
	} else {
		pktID = 0x008C
	}
	text := req.Name + " : " + req.Message + "\x00"
	totalLen := 4 + len(text)
	buf := make([]byte, totalLen)
	binary.LittleEndian.PutUint16(buf[0:], pktID)
	binary.LittleEndian.PutUint16(buf[2:], uint16(totalLen))
	copy(buf[4:], text)
	return buf
}
